from collections import Counter, deque


def background(grid):
    """Return the most frequent cell value in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]


def components(grid, color):
    """Return orthogonally-connected components of a color as lists of (r, c)."""
    seen, comps = set(), []
    H, W = len(grid), len(grid[0])
    for r in range(H):
        for c in range(W):
            if grid[r][c] == color and (r, c) not in seen:
                q, comp = deque([(r, c)]), []
                seen.add((r, c))
                while q:
                    a, b = q.popleft()
                    comp.append((a, b))
                    for da, db in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        na, nb = a + da, b + db
                        if 0 <= na < H and 0 <= nb < W and grid[na][nb] == color and (na, nb) not in seen:
                            seen.add((na, nb))
                            q.append((na, nb))
                comps.append(comp)
    return comps


def is_straight_line(comp):
    """True if a component is a straight orthogonal run of length >= 2."""
    if len(comp) < 2:
        return False
    rs = [r for r, c in comp]; cs = [c for r, c in comp]
    return len(set(rs)) == 1 or len(set(cs)) == 1


def bar_and_marker_colors(grid):
    """Split non-background colors into (bar_color, marker_color) for two-bar puzzles."""
    bg = background(grid)
    colors = {}
    for row in grid:
        for v in row:
            if v != bg:
                colors[v] = colors.get(v, 0) + 1
    bar = None
    for col in colors:
        if all(is_straight_line(c) for c in components(grid, col)):
            bar = col
            break
    marker = [c for c in colors if c != bar][0]
    return bar, marker


def bar_segments(grid, color):
