lib = '''"""Reusable ARC grid helpers (bar/beam family and general utilities)."""
from collections import Counter, deque


def background(grid):
    """Return the most frequent cell value in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]


def components(grid, color):
    """Return orthogonally-connected components of a color as lists of (r, c)."""
    seen, comps = set(), []
    H, W = len(grid), len(grid[0])
    for r in range(H):
        for c in range(W):
            if grid[r][c] == color and (r, c) not in seen:
                q, comp = deque([(r, c)]), []
                seen.add((r, c))
                while q:
                    a, b = q.popleft()
                    comp.append((a, b))
                    for da, db in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        na, nb = a + da, b + db
                        if 0 <= na < H and 0 <= nb < W and grid[na][nb] == color and (na, nb) not in seen:
                            seen.add((na, nb))
                            q.append((na, nb))
                comps.append(comp)
    return comps


def is_straight_line(comp):
    """True if a component is a straight orthogonal run of length >= 2."""
    if len(comp) < 2:
        return False
    rs = [r for r, c in comp]; cs = [c for r, c in comp]
    return len(set(rs)) == 1 or len(set(cs)) == 1


def bar_and_marker_colors(grid):
    """Split non-background colors into (bar_color, marker_color): the bar color's
    components are all straight runs of length >= 2."""
    bg = background(grid)
    colors = set()
    for row in grid:
        for v in row:
            if v != bg:
                colors.add(v)
    bar = None
    for col in colors:
        if all(is_straight_line(c) for c in components(grid, col)):
            bar = col
            break
    marker = [c for c in colors if c != bar][0]
    return bar, marker


def bar_segments(grid, color):
    """Return bar segments as (horizontal, fixed, lo, hi): a horizontal bar occupies
    row `fixed`, columns lo..hi; a vertical bar occupies column `fixed`, rows lo..hi."""
    segs = []
    for comp in components(grid, color):
        rs = [r for r, c in comp]; cs = [c for r, c in comp]
        if len(set(rs)) == 1:
            segs.append((True, rs[0], min(cs), max(cs)))
        elif len(set(cs)) == 1:
            segs.append((False, cs[0], min(rs), max(rs)))
        else:
            raise ValueError("bar segment is not straight")
    return segs


def beam(grid, start, dr, dc, color):
    """Fill cells from start in direction (dr, dc) with color until a non-background cell."""
    bg = background(grid)
    r, c = start[0] + dr, start[1] + dc
    while 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == bg:
        grid[r][c] = color
        r += dr; c += dc


def offset_fill(grid, seg, offsets, color):
    """Fill a bar segment's span positions at the given offsets from its start, over
    the full perpendicular extent, changing background cells only."""
    bg = background(grid)
    horizontal, fixed, lo, hi = seg
    H, W = len(grid), len(grid[0])
    for off in offsets:
        if horizontal:
            c = lo + off
            if 0 <= c < W:
                for r in range(H):
                    if grid[r][c] == bg:
                        grid[r][c] = color
        else:
            r = lo + off
            if 0 <= r < H:
                for c in range(W):
                    if grid[r][c] == bg:
                        grid[r][c] = color
