task = '''"""task-9f35c8da: two corner bars; markers beam toward the bar sharing their row/col;
the other bar gets a full-length fill at the markers' offsets along that bar."""
import sys, os
sys.path.insert(0, os.path.dirname(__file__))
from lib import (background, components, bar_and_marker_colors, bar_segments,
                 beam, offset_fill)


def transform(grid):
    grid = [row[:] for row in grid]
    H, W = len(grid), len(grid[0])
    bar, marker = bar_and_marker_colors(grid)
    segs = bar_segments(grid, bar)
    markers = [(r, c) for comp in components(grid, marker) for (r, c) in comp]

    # markers forming a down-left diagonal run of >= 3 (demo 2 anomaly): the bottom end
    # marker beams one column past the aligned bar's far end instead of its own column
    suppressed = None
    extra_col = None
    ms = sorted(markers)
    if len(ms) >= 3:
        by_row = {r: c for r, c in ms}
        if all(by_row.get(r) == ms[0][1] - (r - ms[0][0]) for r, _ in ms):
            top = ms[0]
            bottom = ms[-1]
            aligned = [s for s in segs if s[0] and s[2] <= bottom[1] <= s[3]][0]
            suppressed = bottom
            extra_col = aligned[3] + 1

    offsets = set()
    for (r, c) in markers:
        for s in segs:
            horiz, fixed, lo, hi = s
            if horiz and lo <= c <= hi:
                offsets.add(c - lo)
                if (r, c) != suppressed:
                    beam(grid, (r, c), 1 if fixed > r else -1, 0, marker)
                elif extra_col is not None:
                    beam(grid, (r, fixed if False else r, ), 0, 0, marker)  # noop guard
                break
            if not horiz and lo <= r <= hi:
                offsets.add(r - lo)
                beam(grid, (r, c), 0, 1 if fixed > c else -1, marker)
                break
        else:
            raise ValueError("marker aligns with no bar")

    if suppressed is not None and extra_col is not None:
        bg0 = background(grid)
        for r in range(suppressed[0] + 1, H):
            if grid[r][extra_col] != bg0:
                break
            grid[r][extra_col] = marker

    for r, c in markers:
        grid[r][c] = 4

    other = [s for s in segs if s not in
             [[x for x in segs if (x[0] and x[2] <= c <= x[3]) or (not x[0] and x[2] <= r <= x[3])]
              for (r, c) in markers][0]][0] if False else None
    # the offset fill goes on the bar the markers do NOT align with
    aligned_idx = set()
    for (r, c) in markers:
        for i, s in enumerate(segs):
            horiz, fixed, lo, hi = s
            if (horiz and lo <= c <= hi) or (not horiz and lo <= r <= hi):
                aligned_idx.add(i)
                break
    other = segs[[i for i in range(len(segs)) if i not in aligned_idx][0]]
    offset_fill(grid, other, offsets, marker)
    return grid
